def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v})
    comps_by_color = {}
    means = {}
    for color in colors:
        seen = set(); comps = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen: continue
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    p=stack.pop(); comp.append(p)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dr,p[1]+dc)
                        if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==color and q not in seen:
                            seen.add(q); stack.append(q)
                comps.append(comp)
        comps_by_color[color]=comps
        pts=[p for comp in comps for p in comp]
        means[color]=sum(c for r,c in pts)/len(pts)
    ordered=sorted(colors,key=lambda color: means[color])
    widths=[]
    for color in ordered:
        widths.append(max(max(c for r,c in comp)-min(c for r,c in comp)+1 for comp in comps_by_color[color]))
    starts=[0]
    for width in widths[:-1]: starts.append(starts[-1]+width+1)
    out=[[0]*w for _ in range(h)]
    for color,x0 in zip(ordered,starts):
        comps=sorted(comps_by_color[color], key=lambda comp:sum(c for r,c in comp)/len(comp))
        for i,comp in enumerate(comps):
            rmin=min(r for r,c in comp); rmax=max(r for r,c in comp); cmin=min(c for r,c in comp)
            bottom=9 if i==0 else 5
            for r,c in comp:
                rr=bottom-(rmax-r); cc=x0+(c-cmin)
                out[rr][cc]=color
    return out
